namespace SimpleBanking;
// TransferSheet.swift: meta row, recipient, amount with piles, purpose, flow card, footer.
internal sealed class TransferWindow : Form
{
    public TransferDraft? Draft {get;private set;}
    public bool SendRequested {get;private set;}
    public bool SaveTemplate {get;private set;}
    public TransferWindow(Account account,TransferDraft? initial,bool demo=false){
        Text=demo?"simplesend · DEMO":"simplesend · Geld senden";ClientSize=new Size(480,590);MinimumSize=new Size(496,560);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",13,GraphicsUnit.Pixel);BackColor=Color.FromArgb(248,250,249);AutoScaleMode=AutoScaleMode.Dpi;AutoScaleDimensions=new SizeF(96,96);Icon=AppArtwork.CreateTrayIcon();Disposed+=(_,_)=>Icon?.Dispose();
        var body=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(22,14,0,14)};Controls.Add(body);
        var meta=new FlowLayoutPanel{Width=420,AutoSize=true,WrapContents=false};var date=new DateTimePicker{ShowCheckBox=true,Checked=initial?.Date!=null,Value=initial?.Date?.ToDateTime(TimeOnly.MinValue)??DateTime.Today,MinDate=DateTime.Today,Format=DateTimePickerFormat.Short,Width=140};meta.Controls.Add(date);meta.Controls.Add(DashboardWindow.Label((demo?"DEMO · ":"")+account.Name,12,true));body.Controls.Add(meta);
        var timing=DashboardWindow.Label("Ohne Termin: sofort",11);body.Controls.Add(timing);
        RoundedCard Card(string title){var card=new RoundedCard{Width=420,MinimumSize=new Size(420,0),Padding=new Padding(14),Margin=new Padding(0,0,0,10)};card.Controls.Add(DashboardWindow.Label(title.ToUpperInvariant(),11,true));body.Controls.Add(card);return card;}
        var recipient=Card("Empfänger");var name=new TextBox{Width=386,PlaceholderText="Empfänger-Name",Text=initial?.Name??"",MaxLength=70};var iban=new TextBox{Width=386,PlaceholderText="IBAN, z.B. DE …",Text=initial?.Iban??""};recipient.Controls.Add(name);recipient.Controls.Add(iban);var ibanState=DashboardWindow.Label("",11);recipient.Controls.Add(ibanState);
        var amountCard=Card("Betrag");var amount=new NumericUpDown{Width=386,Maximum=100000,DecimalPlaces=2,ThousandsSeparator=true,Value=Math.Clamp(initial?.Amount??0,0,100000),Font=new Font("Segoe UI",30,FontStyle.Bold,GraphicsUnit.Pixel)};amountCard.Controls.Add(amount);var balance=DashboardWindow.Label("",12);amountCard.Controls.Add(balance);var piles=new FlowLayoutPanel{AutoSize=true,WrapContents=false};foreach(int value in new[]{10,20,50,100})piles.Controls.Add(DashboardWindow.ActionButton(value.ToString(),()=>amount.Value=value));amountCard.Controls.Add(piles);
        var purposeCard=Card("Verwendungszweck · optional");var purpose=new TextBox{Width=386,MaxLength=140,PlaceholderText="z.B. Miete Mai",Text=initial?.Purpose??""};purposeCard.Controls.Add(purpose);

        var imports=new FlowLayoutPanel{Width=420,AutoSize=true};body.Controls.Add(imports);
        void Fill(TransferDraft parsed){name.Text=parsed.Name;iban.Text=parsed.Iban;amount.Value=Math.Clamp(parsed.Amount,0,amount.Maximum);purpose.Text=parsed.Purpose;}
        imports.Controls.Add(DashboardWindow.ActionButton("Zwischenablage",()=>Fill(DocumentScanner.Parse(Clipboard.GetText(),account.Id))));
        var scan=DashboardWindow.ActionButton("PDF / QR-Bild / Foto …",()=>{});imports.Controls.Add(scan);
        async Task Scan(string path){scan.Enabled=false;try{string text=await Task.Run(()=>DocumentScanner.Read(path));if(IsDisposed)return;var parsed=DocumentScanner.Parse(text,account.Id);if(parsed.Iban.Length==0&&parsed.Amount==0){MessageBox.Show(this,"Keine Überweisungsdaten erkannt. Bitte manuell eintragen.");return;}Fill(parsed);MessageBox.Show(this,"Bitte Empfänger, IBAN, Betrag und Verwendungszweck anhand der Rechnung prüfen.");}catch(Exception ex){if(!IsDisposed)MessageBox.Show(this,"Dokument konnte nicht gelesen werden: "+ex.GetType().Name);}finally{if(!IsDisposed)scan.Enabled=true;}}
        scan.Click+=async(_,_)=>{using var file=new OpenFileDialog{Filter="Rechnung oder QR-Code|*.pdf;*.png;*.jpg;*.jpeg;*.tif;*.tiff;*.bmp;*.gif"};if(file.ShowDialog(this)==DialogResult.OK)await Scan(file.FileName);};AllowDrop=true;DragEnter+=(_,e)=>e.Effect=e.Data?.GetDataPresent(DataFormats.FileDrop)==true?DragDropEffects.Copy:DragDropEffects.None;DragDrop+=async(_,e)=>{if(e.Data?.GetData(DataFormats.FileDrop) is string[] paths&&paths.Length>0)await Scan(paths[0]);};
        body.Controls.Add(DashboardWindow.Label(demo?"DEMO: Keine Zahlung und keine Verbindung zur Bank.":"Rechnung (PDF oder Bild) hier ablegen",11));
        var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=88,Padding=new Padding(14,10,10,6),BackColor=Color.White};Controls.Add(footer);
        void Finish(bool send,bool template){var draft=new TransferDraft(account.Id,name.Text.Trim(),BankingRules.NormalizeIban(iban.Text),amount.Value,purpose.Text.Trim(),date.Checked?DateOnly.FromDateTime(date.Value):null,initial?.RoundupId);string? error=BankingRules.Validate(draft);if(error!=null){MessageBox.Show(this,error);return;}Draft=draft;SendRequested=send;SaveTemplate=template;DialogResult=DialogResult.OK;}
        footer.Controls.Add(DashboardWindow.ActionButton("Entwurf speichern",()=>Finish(false,false)));footer.Controls.Add(DashboardWindow.ActionButton("Als Vorlage speichern",()=>Finish(false,true)));var send=DashboardWindow.ActionButton(demo?"Demo-Versand prüfen":"Überweisung prüfen",()=>Finish(true,false));footer.Controls.Add(send);
        void Update(){bool named=name.Text.Trim().Length>=2,valid=BankingRules.ValidIban(iban.Text);iban.Enabled=named;amountCard.Enabled=named&&valid&&initial?.RoundupId==null;ibanState.Text=iban.Text.Length==0?"":valid?"IBAN gültig":"IBAN noch unvollständig oder ungültig";ibanState.ForeColor=valid?Color.FromArgb(79,138,106):Color.FromArgb(198,90,90);var mood=BalancePresentation.Create(account.BalanceKnown?account.Balance-amount.Value:null,new());amount.ForeColor=mood.Ink;balance.Text=account.BalanceKnown?UiFormat.Money(account.Balance,"EUR")+" verfügbar  →  "+UiFormat.Money(account.Balance-amount.Value,"EUR"):"Kontostand nicht verfügbar";send.Enabled=named&&valid&&amount.Value>0;timing.Text=date.Checked?"Ausführung am "+date.Value.ToString("dd.MM.yyyy"):"Sofort";}
        name.TextChanged+=(_,_)=>Update();iban.TextChanged+=(_,_)=>Update();amount.ValueChanged+=(_,_)=>Update();date.ValueChanged+=(_,_)=>Update();Update();
        if(initial?.RoundupId!=null){name.ReadOnly=true;iban.ReadOnly=true;amountCard.Enabled=false;}
    }
}
